                nxt["posts"].append(action)
                nxt["last"] = action
            nxt["phase"] = "chance"
            return nxt
        nxt["day"] += 1
        nxt["phase"] = "terminal" if nxt["day"] >= HORIZON else "operator"
        return nxt

    def get_current_player(self, state):
